def topological_sort(graph):
    visited = set()
    order = []
    in_stack = set()

    def visit(node):
        if node in in_stack:
            raise ValueError('cycle detected')
        if node in visited:
            return
        visited.add(node)
        in_stack.add(node)
        for dependency in graph.get(node, []):
            visit(dependency)
        in_stack.remove(node)
        order.append(node)

    for node in graph:
        visit(node)
    return order
