def topological_sort(graph):
    visited = set()
    order = []
    # 0: unvisited, 1: visiting, 2: visited
    state = {}

    def visit(node):
        if state.get(node) == 2:
            return
        if state.get(node) == 1:
            raise ValueError('cycle detected')
        state[node] = 1
        for dependency in graph.get(node, []):
            visit(dependency)
        state[node] = 2
        order.append(node)

    for node in graph:
        visit(node)
    return order
