def topological_sort(graph):
    visited = set()
    order = []
    # 0 = unvisited, 1 = visiting, 2 = visited
    state = {node: 0 for node in graph}

    def visit(node):
        if state.get(node, 0) == 2:
            return
        if state.get(node, 0) == 1:
            raise ValueError('cycle detected')
        state[node] = 1
        for dependency in graph.get(node, []):
            visit(dependency)
        order.append(node)
        state[node] = 2

    for node in graph:
        visit(node)
    return order
